import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell, CartesianGrid } from "recharts";

function CustomTooltip({ active, payload }) {
  if (!active || !payload?.length) return null;
  const d = payload[0].payload;
  return (
    <div style={{ background: "var(--color-background-primary)", border: "0.5px solid var(--color-border-secondary)", borderRadius: "var(--border-radius-md)", padding: "8px 12px", fontSize: 13 }}>
      <p style={{ margin: "0 0 4px", fontWeight: 500 }}>{d.shop_name}</p>
      <p style={{ margin: 0, color: "var(--color-text-secondary)" }}>{d.qty?.toLocaleString()} units</p>
    </div>
  );
}

export default function TopShopsByQtyChart({ data = [], loading = false }) {
  if (loading) {
    return (
      <div style={{ border: "0.5px solid var(--color-border-tertiary)", borderRadius: "var(--border-radius-lg)", padding: "1.25rem 1.5rem", height: 320 }}>
        <div style={{ height: 14, width: 180, background: "var(--color-border-tertiary)", borderRadius: 4, marginBottom: 16 }} />
        <div style={{ height: 240, background: "var(--color-background-secondary)", borderRadius: 8 }} />
      </div>
    );
  }

  const chartData = data.slice(0, 10).map((d) => ({
    ...d,
    shortName: d.shop_name.length > 14 ? d.shop_name.slice(0, 14) + "…" : d.shop_name,
  }));

  return (
    <div style={{ border: "0.5px solid var(--color-border-tertiary)", borderRadius: "var(--border-radius-lg)", padding: "1.25rem 1.5rem" }}>
      <p style={{ margin: "0 0 1rem", fontWeight: 500, fontSize: 14 }}>Top shops by qty</p>
      {chartData.length === 0
        ? <p style={{ textAlign: "center", color: "var(--color-text-tertiary)", padding: "2rem 0", margin: 0 }}>No data</p>
        : (
          <ResponsiveContainer width="100%" height={260}>
            <BarChart data={chartData} margin={{ top: 4, right: 8, left: 0, bottom: 60 }}>
              <CartesianGrid vertical={false} stroke="var(--color-border-tertiary)" strokeDasharray="4 4" />
              <XAxis
                dataKey="shortName"
                tick={{ fontSize: 11, fill: "var(--color-text-tertiary)" }}
                axisLine={false}
                tickLine={false}
                angle={-40}
                textAnchor="end"
                interval={0}
              />
              <YAxis
                tick={{ fontSize: 11, fill: "var(--color-text-tertiary)" }}
                axisLine={false}
                tickLine={false}
                width={40}
              />
              <Tooltip content={<CustomTooltip />} cursor={{ fill: "var(--color-background-secondary)" }} />
              <Bar dataKey="qty" radius={[4, 4, 0, 0]} barSize={22}>
                {chartData.map((_, i) => (
                  <Cell key={i} fill="#1D9E75" fillOpacity={1 - i * 0.06} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        )}
    </div>
  );
}
